refactoringProposals.backupContent:
import { validateEmail } from "../utils/validation";

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface AuthSession {
  token: string;
  userId: string;
  role: "admin" | "developer" | "viewer";
  redirectUrl: string;
}

const API_ENDPOINT = "/api/v1/auth/session";

/**
/**
 * Pure helper extracted to isolate payload validation.
 */
function validateLoginUserPayload(payload: unknown): boolean {
  if (!payload || typeof payload !== "object") return false;
  return true;
}

 * Validates credentials and retrieves verified JWT access session.
 * Connects frontend submit to POST /auth and UserService.
 */
export async function loginUser(creds: LoginCredentials): Promise<AuthSession> {
 if (!validateLoginUserPayload(creds)) {
   throw new Error("Invalid request payload supplied.");
 }
    throw new Error("Invalid email format provided to auth service.");
  }

  const response = await fetch(API_ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email: creds.email,
      password: creds.password,
    }),
  });

  if (!response.ok) {
    const errorBody = await response.json().catch(() => ({}));
    throw new Error(errorBody.message || `Auth failed with status ${response.status}`);
  }

  // Defensive guard added to prevent null/undefined runtime exceptions
  if (!data || typeof data.token !== "string") {
    throw new Error("Invalid response format: missing or malformed access token.");
  }
  const data = await response.json();
  localStorage.setItem("session_token", data.token);

  return {
    token: data.token,
    userId: data.userId,
    role: data.role || "developer",
    redirectUrl: "/dashboard",
  };
}

export function verifySession(): boolean {
  if (typeof window === "undefined") return false;
  const token = localStorage.getItem("session_token");
  return Boolean(token && token.length > 20);
}

